$pageTitle='Prompt Manager';$topNavSection='configuration';$BODY_CLASS='hub-page';require __DIR__.'/ui_bootstrap.php';$rows=$uiRepository->rows('prompts');$installations=$uiRepository->rows('installations');$embedded=($_GET['embed']??'')==='1';include __DIR__.'/tmpl/head.html';if(!$embedded)include __DIR__.'/tmpl/navbar.php';
?>
<main class="almsivi-page<?php echo $embedded?' embedded':''; ?>"><header class="almsivi-page-header"><div><h1>Prompt Manager</h1><p>Versioned dialogue prompt documents available to Core Profiles and explicit NPC overrides.</p></div><span class="almsivi-badge"><?php echo count($rows); ?> prompts</span></header><?php if(isset($_GET['status'])): ?><div class="almsivi-status">Prompt saved.</div><?php endif; ?>
<section class="almsivi-card"><h2>Create prompt</h2><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/prompts"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><div class="almsivi-form-grid"><label>Installation<select name="installation_id"><?php foreach($installations as$row): ?><option value="<?php echo almsivi_ui_h($row['installation_id']); ?>"><?php echo almsivi_ui_h($row['display_name']); ?></option><?php endforeach; ?></select></label><label>Name<input name="name" required maxlength="128"></label><label class="wide">Prompt document JSON<textarea name="content_json" required>{"instruction":"Respond in character using only scoped Morrowind context."}</textarea></label></div><div class="almsivi-actions"><button type="submit">Create Prompt</button></div></form></section>
<section class="almsivi-card"><h2>Import prompt</h2><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/prompt-import"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><label>Installation<select name="installation_id"><?php foreach($installations as$row): ?><option value="<?php echo almsivi_ui_h($row['installation_id']); ?>"><?php echo almsivi_ui_h($row['display_name']); ?></option><?php endforeach; ?></select></label><label>Choose JSON file<input type="file" accept="application/json,.json" data-json-import-target="prompt-import-json"></label><label>Portable ALMSIVI prompt JSON<textarea id="prompt-import-json" name="prompt_json" required placeholder="Choose a JSON file or paste its contents here."></textarea></label><button type="submit">Import Prompt</button></form></section>
<section class="almsivi-grid"><?php foreach($rows as$row):$content=is_array($row['content'])?$row['content']:[]; ?><article class="almsivi-card"><div class="almsivi-card-header"><div><h2><?php echo almsivi_ui_h($row['name']); ?></h2><p class="almsivi-muted"><?php echo almsivi_ui_h($row['profile_usage']); ?> explicit assignments</p></div><span class="almsivi-badge">Revision <?php echo almsivi_ui_h($row['current_revision']); ?></span></div><details><summary>Edit prompt</summary><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/configuration-revise"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><input type="hidden" name="kind" value="prompt"><input type="hidden" name="configuration_id" value="<?php echo almsivi_ui_h($row['configuration_id']); ?>"><label>Prompt document JSON<textarea name="content_json" required><?php echo almsivi_ui_h(json_encode($content,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)); ?></textarea></label><label>Revision note<input name="change_reason" required value="Management prompt update"></label><div class="almsivi-actions"><button type="submit">Save Revision</button></div></form></details><details><summary>Revision history</summary><?php $history=is_array($row['revisions'])?$row['revisions']:[];almsivi_ui_table($history); ?><?php $earlier=array_values(array_filter($history,static fn(array$r):bool=>(int)$r['revision']!==(int)$row['current_revision']));if($earlier!==[]): ?><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/configuration-rollback"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><input type="hidden" name="kind" value="prompt"><input type="hidden" name="configuration_id" value="<?php echo almsivi_ui_h($row['configuration_id']); ?>"><label>Restore revision<select name="revision"><?php foreach($earlier as$revision): ?><option value="<?php echo almsivi_ui_h($revision['revision']); ?>">Revision <?php echo almsivi_ui_h($revision['revision']); ?></option><?php endforeach; ?></select></label><button class="secondary" type="submit">Restore</button></form><?php endif; ?></details><div class="almsivi-actions"><a class="btn-base" href="<?php echo almsivi_ui_h($managementBasePath); ?>/exports/prompts/<?php echo almsivi_ui_h($row['configuration_id']); ?>.json">Export</a><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/prompt-clone"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><input type="hidden" name="configuration_id" value="<?php echo almsivi_ui_h($row['configuration_id']); ?>"><label>Clone name<input name="name" required value="<?php echo almsivi_ui_h($row['name'].' copy'); ?>"></label><button class="secondary" type="submit">Clone</button></form><?php if((int)$row['profile_usage']===0): ?><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/configuration-delete" data-confirm="Delete this prompt?"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><input type="hidden" name="kind" value="prompt"><input type="hidden" name="configuration_id" value="<?php echo almsivi_ui_h($row['configuration_id']); ?>"><button class="danger" type="submit">Delete</button></form><?php else: ?><span class="almsivi-muted">Prompt is assigned and cannot be deleted.</span><?php endif; ?></div></article><?php endforeach; ?><?php if($rows===[]): ?><article class="almsivi-card almsivi-empty">No prompt documents exist yet.</article><?php endif; ?></section></main><?php include __DIR__.'/tmpl/footer.html'; ?>
